const config = $input.first().json;
const combinations = config.roles.flatMap(keywords => config.cities.map(location => ({ keywords, location })));
return combinations.map(item => ({ json: { ...item, search_combination_count: combinations.length } }));

const status = Number($json.statusCode);
if (status === 401) throw new Error('Jooble authentication failed (401). Check the configured API key.');
if (status === 429) throw new Error('Jooble rate limit reached (429). Stop requests and retry later.');
if (status >= 400) throw new Error(`Jooble API request failed with HTTP ${status}.`);
let payload = $json.body;
if (typeof payload === 'string') { try { payload = JSON.parse(payload); } catch { throw new Error('Jooble returned malformed JSON.'); } }
if (!payload || !Array.isArray(payload.jobs)) throw new Error('Jooble response is malformed: jobs[] is missing.');
if (payload.jobs.some(job => !job || typeof job !== 'object')) throw new Error('Jooble response is malformed: jobs[] contains a non-object item.');
const usable = payload.jobs.filter(job => job.title && job.link);
const omitted_job_count = payload.jobs.length - usable.length;
const jobs = usable.map(job => ({ ...job, company: job.company || 'Unknown', location: job.location || '', snippet: job.snippet || '', updated: job.updated || null }));
return { json: { ...payload, jobs, api_request_count: 1, omitted_job_count } };
